	"nexus_upstream_request_latency_p50_seconds": {
		help: "p50 request latency in seconds per route (local/frontier/fusion), from sliding window ring buffer (issue #774).",
		typ:  "gauge",
	},
	"nexus_upstream_request_latency_p95_seconds": {
