		out.IntValue = &n
	case uint32:
		n := int64(x)
		out.IntValue = &n
	case uint64:
		if x <= 1<<63-1 {
			n := int64(x)
			out.IntValue = &n
		} else {
			f := float64(x)
			out.DoubleValue = &f
		}
	case float32:
		f := float64(x)
		out.DoubleValue = &f
	case float64:
		out.DoubleValue = &x
	case []any:
		arr := make([]otlpAttrValue, len(x))
		for i, elem := range x {
			arr[i] = encodeAttr(elem)
		}
		out.ArrayValue = &otlpArrayValue{Values: arr}
	case []string:
		arr := make([]otlpAttrValue, len(x))
		for i, elem := range x {
			arr[i] = encodeAttr(elem)
		}
